static int collect_same_gop(void *opaque, void *elem)
{
    DTS2PTSCollect *c = opaque;
    DTS2PTSNode *node = elem;
    if (node->gop == c->gop) {
        if (c->count < c->max)
            c->out[c->count] = node;
        c->count++;
    }
    return 0;
}

